INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (463, 1, 'driver name', 'QEMU 에서 `<driver>` 의 **name** 으로 쓸 수 있는 값은 무엇일까요?', '이름은 하나예요.', NULL, NULL, '[]', 'choice', '["tap", "phy", "qemu", "file"]', 2, '문서는 xen 이 tap, tap2, phy, file 을 지원하는 반면 qemu 는 name 으로 qemu 만 지원하고 type 으로 raw, bochs, qcow2, qed 등을 받는다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 2, 'directsync', '`cache="directsync"` 는 무엇일까요?', '캐시를 우회해요.', NULL, NULL, '[]', 'choice', '["모든 쓰기를 호스트 메모리에만 모아 둔다", "호스트 페이지 캐시를 우회한다", "게스트의 sync 요청을 무시한다", "디스크 캐시를 완전히 끈다"]', 1, '문서는 directsync 가 writethrough 와 같지만 호스트 페이지 캐시를 우회한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 3, 'cache unsafe', '`cache="unsafe"` 는 어떻게 동작할까요?', '이름대로 위험해요.', NULL, NULL, '[]', 'choice', '["게스트의 sync 요청을 무시한다", "모든 쓰기를 즉시 디스크에 기록한다", "호스트 페이지 캐시를 우회한다", "읽기만 캐시하고 쓰기는 거부한다"]', 0, '문서는 unsafe 가 호스트가 모든 디스크 I/O 를 캐시할 수 있고 게스트의 sync 요청이 무시된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 4, 'enospace', '`error_policy="enospace"` 는 언제 도메인을 멈출까요?', '용량 문제예요.', NULL, NULL, '[]', 'choice', '["오류가 나면 언제나 도메인을 멈춘다", "오류를 모두 무시하고 계속한다", "읽기 오류가 날 때만 멈춘다", "호스트 스토리지가 가득 찰 때만 멈춘다"]', 3, '문서는 enospace 가 호스트 스토리지가 가득 찼을 때만 도메인을 일시 중지하고 그 외에는 게스트 OS 에 오류를 보고한다고 설명합니다. stop 은 항상 중지, ignore 는 무시입니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 5, 'rerror_policy', '`rerror_policy` 를 지정하지 않으면 **읽기 오류** 는 어떻게 처리될까요?', '쓰기와 같아요.', NULL, NULL, '[]', 'choice', '["읽기 오류는 항상 무시된다", "읽기 오류는 항상 도메인을 멈춘다", "error_policy 를 읽기에도 쓴다", "읽기 오류는 호스트에만 기록된다"]', 2, '문서는 rerror_policy 가 없으면 error_policy 가 읽기·쓰기 오류 모두에 쓰이고, 있으면 읽기 오류에서 이를 덮어쓰며 enospace 는 읽기 오류에 유효하지 않다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 6, 'discard', '`discard="unmap"` 은 무엇을 허용할까요?', 'trim 이에요.', NULL, NULL, '[]', 'choice', '["discard 요청을 모두 무시한다", "discard 요청을 파일시스템에 전달한다", "쓰기 요청을 압축해서 보낸다", "읽기 요청을 캐시에서 처리한다"]', 1, '문서는 discard 가 unmap(요청을 파일시스템에 전달) 또는 ignore(요청 무시) 값을 받는다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 7, 'copy_on_read', '`copy_on_read="on"` 이 **유용한 경우** 는 언제일까요?', '느린 백킹이에요.', NULL, NULL, '[]', 'choice', '["백킹이 느린 네트워크 위일 때", "이미지가 raw 포맷일 때", "디스크가 CD-ROM 일 때", "게스트가 읽기 전용일 때"]', 0, '문서는 copy_on_read 가 읽은 백킹 파일 내용을 이미지 파일에 복사해 같은 섹터에 반복 접근하지 않게 하며, 백킹 파일이 느린 네트워크에 있을 때 유용하고 기본은 off 라고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 8, 'iotune 0', '`<iotune>` 에서 **지정하지 않거나 0** 인 하위 요소는 무엇을 뜻할까요?', '제한이에요.', NULL, NULL, '[]', 'choice', '["가장 낮은 한도로 제한한다", "호스트 기본 한도를 따른다", "디스크가 비활성화된다", "제한이 없다"]', 3, '문서는 iotune 이 디스크별 I/O 제한을 정하며 지정하지 않았거나 0 인 하위 요소는 제한이 없다는 뜻이고, total_bytes_sec 는 read_bytes_sec·write_bytes_sec 와 함께 쓸 수 없다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 9, 'transient', '`<transient/>` 디스크의 변경 내용은 어떻게 될까요?', '되돌려져요.', NULL, NULL, '[]', 'choice', '["원본 이미지에 즉시 영구 반영된다", "다음 부팅 때 암호화된다", "게스트가 종료될 때 자동으로 되돌려진다", "다른 도메인과 자동으로 공유된다"]', 2, '문서는 transient 가 게스트가 종료될 때 장치 내용 변경을 자동으로 되돌리며, QEMU 는 임시 파일을 원본경로.TRANSIENT-도메인이름 으로 저장한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 10, '캐시 속성', '디스크 **캐시 방식** 을 정하는 속성입니다. 빈칸을 채우세요.', '캐시예요.', NULL, NULL, '[]', 'fill', '["cache", "io", "discard", "error_policy"]', NULL, 'cache 는 default·none·writethrough·writeback·directsync·unsafe 를 받습니다. io 는 I/O 정책, discard 는 trim 처리, error_policy 는 오류 동작입니다.', '[0]', '<driver name="qemu" type="qcow2" {0}="none"/>', NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 11, 'I/O 정책', 'I/O 정책(**threads·native·io_uring**)을 고르는 속성입니다. 빈칸을 채우세요.', 'I/O 의 io 예요.', NULL, NULL, '[]', 'fill', '["io", "cache", "discard", "copy_on_read"]', NULL, 'io 속성이 qemu 게스트에서 threads, native(0.8.8), io_uring(6.3.0)을 받습니다.', '[0]', '<driver name="qemu" type="raw" {0}="threads"/>', NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]'),
  (463, 12, 'I/O 제한', '디스크 I/O 제한을 거는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '찾기 → 추가 → 한도 → 반영이에요.', NULL, NULL, '[]', 'order', '["제한할 `<disk>` 요소를 찾는다", "`<iotune>` 하위 요소를 추가한다", "`total_bytes_sec` 나 `total_iops_sec` 로 한도를 정한다", "도메인 XML 을 정의해 반영한다"]', NULL, '문서의 iotune 설명(디스크별 I/O 제한, 0 은 무제한)을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "libvirt Domain XML format", "url": "https://libvirt.org/formatdomain.html"}]');
